(async () => {
  const w_slots = {
  "array": [
    1,
    2,
    3,
    4
  ],
  "predicate": {
    "op": "mod",
    "operand": 2
  }
};
  const w_answer = await (async () => {
const slots = w_slots;
const kept = slots.array.filter((value) => value % slots.predicate.operand === slots.predicate.op === "mod");
return kept.length + " elements.";
  })();
  console.log(String(w_answer));
})();

